changeSet.sql:
UPDATE clinlims.inventory_item
SET code = LEFT(TRIM(BOTH '_' FROM REGEXP_REPLACE(UPPER(name), '[^A-Z0-9]+', '_', 'g')), 64)
WHERE code IS NULL;

UPDATE clinlims.inventory_item
SET code = 'ITEM_' || id
WHERE code IS NULL OR code = '';

DO $$
DECLARE
    remaining INTEGER;
    passes INTEGER := 0;
    dup_id BIGINT;
    suffix INTEGER;
    candidate TEXT;
BEGIN
    LOOP
        UPDATE clinlims.inventory_item outer_item
        SET code = LEFT(outer_item.code, GREATEST(1, 64 - LENGTH('_' || outer_item.id)))
                   || '_' || outer_item.id
        WHERE EXISTS (
            SELECT 1 FROM clinlims.inventory_item inner_item
            WHERE inner_item.code = outer_item.code
            AND inner_item.id < outer_item.id
        );

        SELECT COUNT(*) INTO remaining FROM (
            SELECT code FROM clinlims.inventory_item
            GROUP BY code HAVING COUNT(*) > 1
        ) duplicates;

        EXIT WHEN remaining = 0;

        passes := passes + 1;
        IF passes >= 5 THEN
            FOR dup_id IN
                SELECT outer_item.id FROM clinlims.inventory_item outer_item
                WHERE EXISTS (
                    SELECT 1 FROM clinlims.inventory_item inner_item
                    WHERE inner_item.code = outer_item.code
                    AND inner_item.id <> outer_item.id
                )
                ORDER BY outer_item.id
            LOOP
                suffix := 1;
                LOOP
                    candidate := 'ITEM_' || dup_id;
                    IF suffix > 1 THEN
                        candidate := LEFT(candidate, GREATEST(1, 64 - LENGTH('_' || suffix)))
                                     || '_' || suffix;
                    END IF;
                    EXIT WHEN NOT EXISTS (
                        SELECT 1 FROM clinlims.inventory_item taken
                        WHERE taken.code = candidate AND taken.id <> dup_id
                    );
                    suffix := suffix + 1;
                END LOOP;
                UPDATE clinlims.inventory_item SET code = candidate WHERE id = dup_id;
            END LOOP;
            EXIT;
        END IF;
    END LOOP;
END $$;
